using LogbookSqlServer.Data;using LogbookSqlServer.Models;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;
namespace LogbookSqlServer.Controllers;
[ApiController][Route("api/beneficiaries")][Authorize] public class BeneficiariesController(LogbookDbContext db):ControllerBase {
 [HttpGet] public async Task<IActionResult> All([FromQuery]string? search,[FromQuery]string? status){var q=db.Beneficiaries.AsNoTracking().AsQueryable();if(!string.IsNullOrWhiteSpace(search))q=q.Where(x=>x.FullName.Contains(search)||(x.CitizenId!=null&&x.CitizenId.Contains(search))||(x.Province!=null&&x.Province.Contains(search))||(x.District!=null&&x.District.Contains(search)));if(!string.IsNullOrWhiteSpace(status))q=q.Where(x=>x.AssistanceStatus==status);return Ok(await q.OrderByDescending(x=>x.UpdatedAt).ToListAsync());}
 [HttpGet("{id:int}")] public async Task<IActionResult> Get(int id){var x=await db.Beneficiaries.FindAsync(id);return x==null?NotFound(new{message="ไม่พบข้อมูล"}):Ok(x);}
 [HttpPost] public async Task<IActionResult> Create(Beneficiary x){var err=Validate(x);if(err!=null)return BadRequest(new{message=err});if(!string.IsNullOrWhiteSpace(x.CitizenId)&&await db.Beneficiaries.AnyAsync(y=>y.CitizenId==x.CitizenId))return Conflict(new{message="เลขบัตรประชาชนนี้มีในระบบแล้ว"});x.Id=0;x.CreatedAt=x.UpdatedAt=DateTime.UtcNow;db.Beneficiaries.Add(x);await db.SaveChangesAsync();return CreatedAtAction(nameof(Get),new{id=x.Id},x);}
 [HttpPut("{id:int}")] public async Task<IActionResult> Update(int id,Beneficiary x){var a=await db.Beneficiaries.FindAsync(id);if(a==null)return NotFound(new{message="ไม่พบข้อมูล"});var err=Validate(x);if(err!=null)return BadRequest(new{message=err});if(!string.IsNullOrWhiteSpace(x.CitizenId)&&await db.Beneficiaries.AnyAsync(y=>y.CitizenId==x.CitizenId&&y.Id!=id))return Conflict(new{message="เลขบัตรประชาชนนี้มีในระบบแล้ว"});a.CitizenId=x.CitizenId;a.FullName=x.FullName;a.Age=x.Age;a.Vulnerability=x.Vulnerability;a.Subdistrict=x.Subdistrict;a.District=x.District;a.Province=x.Province;a.Agency=x.Agency;a.AnnualBudget=x.AnnualBudget;a.HouseholdIncome=x.HouseholdIncome;a.HouseholdMembers=x.HouseholdMembers;a.AssistanceStatus=x.AssistanceStatus;a.Notes=x.Notes;a.UpdatedAt=DateTime.UtcNow;await db.SaveChangesAsync();return Ok(a);}
 [HttpDelete("{id:int}")] public async Task<IActionResult> Delete(int id){var x=await db.Beneficiaries.FindAsync(id);if(x==null)return NotFound(new{message="ไม่พบข้อมูล"});db.Beneficiaries.Remove(x);await db.SaveChangesAsync();return NoContent();}
 static string? Validate(Beneficiary x){if(string.IsNullOrWhiteSpace(x.FullName))return "กรุณากรอกชื่อ-นามสกุล";if(!string.IsNullOrEmpty(x.CitizenId)&&(x.CitizenId.Length!=13||!x.CitizenId.All(char.IsDigit)))return "เลขบัตรประชาชนต้องเป็นตัวเลข 13 หลัก";if(x.Age is <0 or >120)return "อายุต้องอยู่ระหว่าง 0 ถึง 120 ปี";if(x.HouseholdIncome<0||x.AnnualBudget<0)return "จำนวนเงินต้องไม่ติดลบ";return null;}
}